/// The exact-score map, part ten, and the goal outlook on the same pregame body.
@MainActor
final class SoccerExactScoreAdapter10868Tests: XCTestCase {
    private typealias F = SoccerRetained10868
    private typealias X = SoccerExactRetained10868
    private typealias E = SoccerExactScoreAdapter10868
    private typealias R = SoccerPropReadingAdapter10868
    private typealias G = SoccerGoalsAdapter10868

    private func map(_ detail: String, _ markets: String, descriptor: E.Descriptor? = X.hullDescriptor,
                     now: Date, scope: String? = nil,
                     originals: [String: String] = [:]) throws -> ExactScoreMapInput10868 {
        try XCTUnwrap(E.input(try F.detail(detail), markets: try F.markets(markets), descriptor: descriptor,
                              host: F.propHost(now), selectedScopeID: scope, selectedOriginals: originals))
    }

    private func scope(_ input: ExactScoreMapInput10868, _ id: String) throws -> ExactScoreMapScope10868 {
        try XCTUnwrap(input.scopes.first { $0.id == id })
    }

    private func original(_ scope: ExactScoreMapScope10868, _ id: String) throws -> ExactScoreMapOriginal10868 {
        try XCTUnwrap(scope.originals.first { $0.id == id })
    }

    /// Every descriptor identity of a scope, in the descriptor's order.
    private func listed(_ id: String) -> [String] {
        (X.hullDescriptor.scopes.first { $0.id == id }?.originals ?? [])
            .map { $0.outcomeIDs.map(String.init).joined(separator: "+") }
    }

    private func clock(_ stamp: String, _ now: Date) -> String {
        SoccerMatchPageAdapter10868.clockWords(stamp.asDate!, host: F.propHost(now).words)
    }

    /// Part three's own reading of a served row before kickoff.
    private func recorded(_ row: GameMarketOther, now: Date) throws -> ExactScoreMapPregame10868 {
        let at = try XCTUnwrap(row.observedAt?.asDate)
        return .recorded(E.observation(R.observation(try XCTUnwrap(row.probability), at: at, lead: R.Words.recorded,
                                                     venue: SourceLabels.label(for: row.source),
                                                     host: F.propHost(now))))
    }

    /// CONSTRUCTED: `hullDescriptor` with one scope's originals rewritten; every
    /// other field and scope unchanged.
    private func rebuilt(_ id: String,
                         _ change: ([E.Descriptor.Original]) -> [E.Descriptor.Original]) -> E.Descriptor {
        E.Descriptor(eventID: X.hullDescriptor.eventID, scopes: X.hullDescriptor.scopes.map { s in
            guard s.id == id else { return s }
            return E.Descriptor.Scope(id: s.id, label: s.label, marketID: s.marketID, periodID: s.periodID,
                                      homeGoals: s.homeGoals, awayGoals: s.awayGoals, scaleUpper: s.scaleUpper,
                                      originals: change(s.originals))
        })
    }

    // MARK: - The retained bodies

    func testTheRetainedBodiesAreVerbatimAndDecodeThroughTheProductionModels() throws {
        XCTAssertEqual(F.sha256(X.hullFinalDetail), "613123df55db40fe308eef46d51ae07da1e035653622b8bc9870e7048d231f9d")
        let final = try F.detail(X.hullFinalDetail)
        XCTAssertEqual(final.id, 15311089)
        XCTAssertTrue(EventState.isFinished(final.status))
        XCTAssertEqual(final.homeScore, 2)
        XCTAssertEqual(final.awayScore, 2)

        let pregame = try F.markets(X.hullExactMarkets)
        XCTAssertEqual(pregame.eventId, 15311089)
        XCTAssertEqual(pregame.other?.count, 57)
        XCTAssertEqual(pregame.other?.filter { $0._marketId == 62939468 }.count, 37)
        XCTAssertEqual(pregame.other?.filter { $0._marketId == 64002155 }.count, 9)
        XCTAssertEqual(pregame.totals?.count, 9)
        XCTAssertEqual(pregame.gameQuestionMatrix?.questions.count, 7)
        XCTAssertEqual(pregame.gameQuestionMatrix?.droppedQuestions, 0)

        let graded = try F.markets(X.hullFinalMarkets)
        XCTAssertEqual(graded.other?.count, 37)
        XCTAssertTrue(graded.other?.allSatisfy { $0._marketId == 62939468 } ?? false)
        XCTAssertEqual(graded.gameQuestionMatrix?.questions.map(\.questionKey), ["m:62939468"])
        XCTAssertTrue(graded.gameQuestionMatrix?.questions[0].options.allSatisfy { $0.pregameReading == nil } ?? false)
        // The retained question stays incomplete although its counts agree.
        XCTAssertEqual(graded.gameQuestionMatrix?.questions[0].complete, false)
    }

    // MARK: - Before kickoff

    /// CONSTRUCTED `now`: eight minutes after the rows' own clocks.
    func testBeforeKickoffEveryListedScoreOfBothScopesIsOnTheMapWithItsOwnChanceAndClock() throws {
        let input = try map(F.hullDetail, X.hullExactMarkets, now: X.preKickoffNow)
        XCTAssertEqual(input.phase, .before)
        XCTAssertEqual(input.title, E.Words.title)
        XCTAssertEqual(input.intro, E.Words.beforeIntro)
        XCTAssertEqual(input.words, E.Words.map)
        XCTAssertEqual(input.legend, E.Words.legend)
        XCTAssertEqual(input.scopes.map(\.id), ["full", "first"])
        XCTAssertEqual(input.scopes.map(\.label), ["Full match", "First half"])
        // The owner's first scope is shown; no score is chosen for the reader.
        XCTAssertEqual(input.selectedScopeID, "full")
        XCTAssertNil(input.selectedOriginalID)
        XCTAssertEqual(input.originalSelection(in: try scope(input, "full")), .unselected)

        let full = try scope(input, "full")
        let first = try scope(input, "first")
        // All 46 originals, each by its served id, in the descriptor's order.
        XCTAssertEqual(full.originals.map(\.id), listed("full"))
        XCTAssertEqual(first.originals.map(\.id), listed("first"))
        XCTAssertEqual(full.originals.count + first.originals.count, 46)
        XCTAssertEqual(full.originals.filter { $0.placement == .nonGrid }.map(\.id), ["245266693"])
        XCTAssertEqual(first.originals.filter { $0.placement == .nonGrid }.map(\.id), ["244588610"])
        XCTAssertEqual(input.cells(full).count, 36)
        XCTAssertEqual(input.cells(first).count, 9)
        XCTAssertEqual(input.choices(in: full).map(\.id), ["245266693"])
        XCTAssertEqual(input.choices(in: first).map(\.id), ["244588610"])

        // First-half 2–2 is not a listed original: a dashed coordinate, never invented.
        XCTAssertEqual(input.slot(at: ExactScoreMapPosition10868(row: 2, column: 2), in: first), .notListed)
        XCTAssertFalse(first.originals.contains { $0.placement == .grid(home: 2, away: 2) })
        XCTAssertFalse(input.cells(full).contains { $0.slot == .notListed })

        // Each original: its own served chance at its own clock, its served
        // name, no current reading and no result before play.
        let served = try XCTUnwrap(try F.markets(X.hullExactMarkets).other)
        for each in [full, first] {
            for original in each.originals {
                let row = try XCTUnwrap(served.first {
                    ($0.contributorOutcomeIds ?? []).map(String.init).joined(separator: "+") == original.id
                })
                XCTAssertEqual(original.label, row.outcomeName)
                XCTAssertEqual(original.pregame, try recorded(row, now: X.preKickoffNow), original.id)
                XCTAssertEqual(original.current, .unavailable(R.Words.inPlayUnavailable))
                XCTAssertEqual(original.result, .unconfirmed(R.Words.resultUnavailable))
                XCTAssertFalse(input.showsResult(original))
                XCTAssertEqual(input.comparisons(original).map(\.title), [E.Words.map.pregameTitle])
            }
        }
        // Never normalised: the full match keeps its raw pre-match sum.
        let sum = full.originals.compactMap { $0.pregame.observation?.probability }.reduce(0, +)
        XCTAssertEqual(sum, 1.0001, accuracy: 0.000_000_1)
        XCTAssertEqual(try original(full, "237459055").pregame.observation?.text, formatProbability(0.0398))
        // The owner's scale bounds, ticks as scale words.
        XCTAssertEqual(full.scale, ExactScoreMapScale10868(lower: 0, upper: 0.1, ticks: [
            ExactScoreMapTick10868(value: 0, text: "0%"), ExactScoreMapTick10868(value: 0.05, text: "5%"),
            ExactScoreMapTick10868(value: 0.1, text: "10%")]))
        XCTAssertEqual(first.scale.upper, 0.4)
        // Before play: no actual score, no result outline.
        XCTAssertNil(full.actual)
        XCTAssertNil(first.actual)
        XCTAssertNil(input.visibleActual(full))
        XCTAssertFalse(input.keyUse(full).result)
    }

    /// At the body's own capture instant every exact-score quote is over five
    /// hours old: nothing is shaded, and every score is still listed.
    func testAtTheCaptureInstantEveryPreKickoffQuoteIsTooOldToShowButEveryScoreStaysListed() throws {
        let input = try map(F.hullDetail, X.hullExactMarkets, now: F.hullNow)
        XCTAssertEqual(input.scopes.map { $0.originals.count }, [37, 9])
        for each in input.scopes {
            XCTAssertTrue(each.originals.allSatisfy { $0.pregame == .unavailable(R.Words.noRecentUpdate) })
            XCTAssertTrue(input.cells(each).allSatisfy { $0.fill == .blank })
            XCTAssertTrue(input.keyUse(each).unavailable)
        }
    }

    /// CONSTRUCTED: only `observed_at` of the full-match 2–2 row (237459055) changes.
    func testEachOriginalKeepsItsOwnClock() throws {
        let stamp = "2026-10-10T23:36:00+00:00"
        let edited = try F.editedRow(X.hullExactMarkets, outcomeID: 237459055, setting: ["observed_at": stamp])
        let base = try map(F.hullDetail, X.hullExactMarkets, now: X.preKickoffNow)
        let moved = try map(F.hullDetail, edited, now: X.preKickoffNow)
        let before = try scope(base, "full")
        let after = try scope(moved, "full")
        XCTAssertEqual(zip(before.originals, after.originals).filter { $0.0 != $0.1 }.map { $0.1.id }, ["237459055"])
        XCTAssertEqual(try original(after, "237459055").pregame.observation?.detail,
                       SoccerMatchPageAdapter10868.joined(["\(R.Words.recorded) \(clock(stamp, X.preKickoffNow))",
                                                           SourceLabels.label(for: "polymarket")]))
        XCTAssertEqual(try scope(moved, "first"), try scope(base, "first"))
    }

    func testTheFirstHalfKeepsItsOwnIdentitiesAndAHeldScoreIsNeverMovedToAnother() throws {
        let input = try map(F.hullDetail, X.hullExactMarkets, now: X.preKickoffNow, scope: "first",
                            originals: ["first": "244588607", "full": "237459055"])
        XCTAssertEqual(input.selectedScopeID, "first")
        XCTAssertEqual(input.selectedOriginalID, "244588607")
        let first = try scope(input, "first")
        guard case .selected(let held) = input.originalSelection(in: first) else { return XCTFail("the held 0–0") }
        XCTAssertEqual(held.pregame.observation?.probability, 0.307)
        // The two scopes share no original.
        XCTAssertTrue(Set(first.originals.map(\.id)).isDisjoint(with: Set(try scope(input, "full").originals.map(\.id))))

        // A full-match score held under the first half is unavailable there:
        // no neighbour, no step — only the owner's recovery.
        let foreign = try map(F.hullDetail, X.hullExactMarkets, now: X.preKickoffNow, scope: "first",
                              originals: ["first": "237459055"])
        XCTAssertEqual(foreign.originalSelection(in: try scope(foreign, "first")), .missing("237459055"))
        XCTAssertNil(foreign.stepAction(1, canSelect: true))
        XCTAssertEqual(foreign.recoverAction(canRecover: true), .recover)
        // A held scope the owner no longer lists is unavailable; no other is chosen.
        let gone = try map(F.hullDetail, X.hullExactMarkets, now: X.preKickoffNow, scope: "second")
        XCTAssertEqual(gone.scopeSelection, .missing("second"))
    }

    // MARK: - During play (CONSTRUCTED variant)

    /// CONSTRUCTED live variant: the Hull detail with only `status`,
    /// `home_score`, `away_score` and `score_observed_at` changed; the pregame
    /// markets body with only `observed_at` changed on the full-match 1–1 row
    /// (238846931) and the first-half 0–0 row (244588607). Not captured live
    /// evidence.
    func testDuringPlayAFullMatchQuoteOnItsOwnRecentClockIsCurrentAndAFirstHalfQuoteStaysDatedHistory() throws {
        let stamp = "2026-10-11T13:15:00+00:00"
        let detail = try F.edited(F.hullDetail, setting: ["status": "live", "home_score": 1, "away_score": 0,
                                                          "score_observed_at": "2026-10-11T13:14:00+00:00"])
        var markets = try F.editedRow(X.hullExactMarkets, outcomeID: 238846931, setting: ["observed_at": stamp])
        markets = try F.editedRow(markets, outcomeID: 244588607, setting: ["observed_at": stamp])
        let input = try map(detail, markets, now: X.liveNow)
        let host = F.propHost(X.liveNow)
        let venue = SourceLabels.label(for: "polymarket")
        XCTAssertEqual(input.phase, .during)
        XCTAssertEqual(input.intro, E.Words.liveIntro)

        let full = try scope(input, "full")
        let oneOne = try original(full, "238846931")
        XCTAssertEqual(oneOne.current, .recorded(E.observation(R.observation(
            0.0952, at: stamp.asDate!, lead: R.Words.recorded, venue: venue, host: host))))
        // Observed before kickoff: no in-play chance, never shown as current.
        XCTAssertEqual(try original(full, "238846934").current, .unavailable(R.Words.inPlayUnavailable))
        // Once started the pre-match slot is the stored pin — none is served
        // here, and this pregame body's option says `no_pregame_pin`: the
        // producer's own statement, so "not recorded".
        XCTAssertEqual(try F.markets(markets).gameQuestionMatrix?.questions
            .first { $0.questionKey == "m:62939468" }?.options
            .first { $0.contributorOutcomeIds == [238846931] }?.comparison?.reason, R.noPregamePinReason)
        XCTAssertEqual(oneOne.pregame, .unavailable(R.Words.preMatchNotRecorded))
        XCTAssertEqual(input.comparisons(oneOne).map(\.title), [E.Words.map.pregameTitle, E.Words.map.currentTitle])

        // The half's recent quote on its own clock is still only dated history.
        let first = try scope(input, "first")
        XCTAssertEqual(try original(first, "244588607").current, .withheld(R.Words.periodQuote(
            formatProbability(0.307), clock: clock(stamp, X.liveNow), venue: venue)))
        XCTAssertFalse(first.originals.contains {
            if case .recorded = $0.current { return true }
            return false
        })

        // The score so far is its own line on its own clock; it grades nothing.
        let names = SoccerMatchPageAdapter10868.names(try F.detail(detail))
        XCTAssertEqual(full.actual, ExactScoreMapActual10868(
            title: E.Words.scoreSoFar,
            text: "\(names.home) 1–0 \(names.away) · \(E.Words.observed) \(clock("2026-10-11T13:14:00+00:00", X.liveNow))"))
        XCTAssertNil(first.actual)
        XCTAssertTrue(input.scopes.allSatisfy { $0.originals.allSatisfy { !$0.result.isAdmitted } })
    }

    // MARK: - After the final

    func testAfterTheFinalEachFullMatchOriginalKeepsItsOwnGradeAndEveryFirstHalfOriginalStaysUnconfirmed() throws {
        let input = try map(X.hullFinalDetail, X.hullFinalMarkets, now: X.finalNow)
        let names = SoccerMatchPageAdapter10868.names(try F.detail(X.hullFinalDetail))
        XCTAssertEqual(input.phase, .final)
        XCTAssertEqual(input.intro, E.Words.finalIntro)

        let full = try scope(input, "full")
        XCTAssertEqual(full.originals.map(\.id), listed("full"))
        XCTAssertEqual(full.originals.filter { $0.result == .won(OutcomeVerdict.won.label) }.map(\.id), ["237459055"])
        XCTAssertEqual(full.originals.filter { $0.result == .lost(OutcomeVerdict.lost.label) }.count, 36)
        // No served pre-match pin on any of the 37 (their comparison says only
        // `not_quoted`): unavailable — never "not recorded", never the settled 0/1.
        XCTAssertTrue(full.originals.allSatisfy { $0.pregame == .unavailable(R.Words.preMatchUnavailable) })
        XCTAssertTrue(full.originals.allSatisfy { $0.current == .unavailable(R.Words.inPlayUnavailable) })
        // The actual score is its own line; only the venue's own grade outlines a cell.
        XCTAssertEqual(full.actual, ExactScoreMapActual10868(title: E.Words.finalScore,
                                                             text: "\(names.home) 2–2 \(names.away)"))
        XCTAssertEqual(input.cells(full).filter(\.showsResult).count, 1)

        // The first-half family has left the payload: all nine stay listed by
        // the owner's held catalogue, every result unconfirmed — not only Other.
        let first = try scope(input, "first")
        XCTAssertEqual(first.originals.map(\.id), listed("first"))
        XCTAssertEqual(first.originals.map(\.label), X.hullDescriptor.scopes[1].originals.map(\.label))
        XCTAssertEqual(first.originals.map(\.placement), X.hullDescriptor.scopes[1].originals.map(\.placement))
        XCTAssertTrue(first.originals.allSatisfy { $0.result == .unconfirmed(R.Words.resultUnavailable) })
        XCTAssertTrue(first.originals.allSatisfy { $0.pregame == .unavailable(R.Words.preMatchUnavailable) })
        XCTAssertFalse(first.originals.contains { input.showsResult($0) })
        XCTAssertNil(first.actual)
        XCTAssertEqual(input.slot(at: ExactScoreMapPosition10868(row: 2, column: 2), in: first), .notListed)
        XCTAssertEqual(input.comparisons(first.originals[0]).map(\.reading),
                       [.words(R.Words.preMatchUnavailable), .result(.unconfirmed(R.Words.resultUnavailable))])
    }

    /// The nine first-half originals the completed body no longer serves: the
    /// payload's silence is not the producer's statement that no pre-match
    /// price was recorded, so each is "unavailable" — never "not recorded" —
    /// and no figure is invented for any of them, although the pregame body
    /// served one for every one.
    func testTheNineHeldFirstHalfOriginalsHaveNoInventedChanceAndAreUnavailableNotUnrecorded() throws {
        let input = try map(X.hullFinalDetail, X.hullFinalMarkets, now: X.finalNow)
        let first = try scope(input, "first")
        XCTAssertEqual(first.originals.count, 9)
        XCTAssertTrue(first.originals.allSatisfy { $0.pregame.observation == nil })
        XCTAssertFalse(first.originals.contains { $0.pregame == .unavailable(R.Words.preMatchNotRecorded) })
        XCTAssertTrue(first.originals.allSatisfy {
            input.comparisons($0).first?.reading == .words(R.Words.preMatchUnavailable)
        })
        // The pregame body did price every one of them.
        let pregame = try XCTUnwrap(try F.markets(X.hullExactMarkets).other)
        for held in first.originals {
            XCTAssertNotNil(pregame.first {
                ($0.contributorOutcomeIds ?? []).map(String.init).joined(separator: "+") == held.id
            }?.probability, held.id)
        }
    }

    /// CONTROL, unknown contract: the completed body with only the matrix
    /// `contract` changed. No matrix grade or pin is read; every full-match
    /// original stays, its result the venue's own settlement alone.
    func testAnUnsupportedMatrixKeepsEveryScoreAndTheVenuesOwnGrades() throws {
        let body = try F.editedMatrix(X.hullFinalMarkets, setting: ["contract": "10238.v2"])
        let input = try map(X.hullFinalDetail, body, now: X.finalNow)
        let real = try map(X.hullFinalDetail, X.hullFinalMarkets, now: X.finalNow)
        let full = try scope(input, "full")
        XCTAssertEqual(full.originals.map(\.id), try scope(real, "full").originals.map(\.id))
        XCTAssertEqual(full.originals.map(\.result), try scope(real, "full").originals.map(\.result))
        XCTAssertTrue(full.originals.allSatisfy { $0.pregame == .unavailable(R.Words.preMatchUnavailable) })
        XCTAssertEqual(try scope(input, "first"), try scope(real, "first"))
    }

    // MARK: - Membership the owner did not describe, and duplicates

    /// CONSTRUCTED descriptor: `hullDescriptor` without its full-match 1–1 entry.
    func testAServedScoreTheOwnerDidNotDescribeIsStillAChoiceAndNeverGetsACoordinate() throws {
        let descriptor = rebuilt("full") { $0.filter { $0.outcomeIDs != [238846931] } }
        let input = try map(F.hullDetail, X.hullExactMarkets, descriptor: descriptor, now: X.preKickoffNow)
        let full = try scope(input, "full")
        XCTAssertEqual(full.originals.count, 37)
        XCTAssertEqual(full.originals.last?.id, "238846931")
        XCTAssertEqual(full.originals.last?.placement, .nonGrid)
        XCTAssertEqual(input.slot(at: ExactScoreMapPosition10868(row: 1, column: 1), in: full), .notListed)
        XCTAssertEqual(input.choices(in: full).map(\.id), ["245266693", "238846931"])
    }

    func testASharedCoordinateOrASharedIdentityChoosesNothing() throws {
        // CONSTRUCTED descriptor: the first-half 1–1 entry given the 1–0 coordinate.
        let shared = rebuilt("first") { list in
            list.map { listed in
                listed.outcomeIDs == [242337399]
                    ? E.Descriptor.Original(outcomeIDs: listed.outcomeIDs, placement: .grid(home: 1, away: 0),
                                            label: listed.label)
                    : listed
            }
        }
        let input = try map(F.hullDetail, X.hullExactMarkets, descriptor: shared, now: X.preKickoffNow, scope: "first")
        let first = try scope(input, "first")
        let oneNil = ExactScoreMapPosition10868(row: 1, column: 0)
        XCTAssertEqual(input.slot(at: oneNil, in: first), .ambiguous)
        XCTAssertNil(input.tapAction(at: oneNil, canSelect: true))
        XCTAssertEqual(input.slot(at: ExactScoreMapPosition10868(row: 1, column: 1), in: first), .notListed)
        XCTAssertEqual(Set(input.choices(in: first).map(\.id)), ["242337398", "242337399", "244588610"])

        // CONSTRUCTED descriptor: the full-match 0–0 entry listed twice.
        let twice = rebuilt("full") { $0 + [$0[0]] }
        let doubled = try map(F.hullDetail, X.hullExactMarkets, descriptor: twice, now: X.preKickoffNow)
        let full = try scope(doubled, "full")
        XCTAssertEqual(full.originals.filter { $0.id == "238846934" }.count, 2)
        XCTAssertFalse(doubled.isUniqueOriginal("238846934", in: full))
        XCTAssertNil(doubled.selectAction(full.originals[0], canSelect: true))
        XCTAssertEqual(doubled.slot(at: ExactScoreMapPosition10868(row: 0, column: 0), in: full), .ambiguous)
    }

    // MARK: - Another event admits nothing

    func testAnotherEventsDescriptorOrMarketsAdmitNothing() throws {
        let event = try F.detail(F.hullDetail)
        let host = F.propHost(X.preKickoffNow)
        let own = try F.markets(X.hullExactMarkets)
        XCTAssertNotNil(E.input(event, markets: own, descriptor: X.hullDescriptor, host: host))
        XCTAssertNil(E.input(event, markets: own, descriptor: nil, host: host))
        XCTAssertNil(E.input(event, markets: nil, descriptor: X.hullDescriptor, host: host))
        // CONSTRUCTED: the descriptor with only its event id changed.
        let foreign = E.Descriptor(eventID: 15311090, scopes: X.hullDescriptor.scopes)
        XCTAssertNil(E.input(event, markets: own, descriptor: foreign, host: host))
        XCTAssertEqual(foreign.periodMarketIDs(for: event), [])
        XCTAssertEqual(X.hullDescriptor.periodMarketIDs(for: event), [64002155])
        // CONSTRUCTED: the markets body with only `event_id` changed.
        let elsewhere = try F.markets(try F.edited(X.hullExactMarkets, setting: ["event_id": 15311090]))
        XCTAssertNil(E.input(event, markets: elsewhere, descriptor: X.hullDescriptor, host: host))
        // CONSTRUCTED: a descriptor whose market ids this body does not serve —
        // no map, rather than an all-blank one.
        let unserved = E.Descriptor(eventID: 15311089, scopes: X.hullDescriptor.scopes.map { s in
            E.Descriptor.Scope(id: s.id, label: s.label, marketID: s.marketID + 1, periodID: s.periodID,
                               homeGoals: s.homeGoals, awayGoals: s.awayGoals, scaleUpper: s.scaleUpper,
                               originals: s.originals)
        })
        XCTAssertNil(E.input(event, markets: own, descriptor: unserved, host: host))
    }

    func testScaleTicksAreTheOwnersBoundAndAnUnusableBoundShadesNothing() {
        XCTAssertEqual(E.scale(0.1).ticks.map(\.text), ["0%", "5%", "10%"])
        XCTAssertEqual(E.scale(0.4).ticks.map(\.text), ["0%", "20%", "40%"])
        XCTAssertEqual(E.scale(0.15).ticks.map(\.text), ["0%", "7.5%", "15%"])
        XCTAssertTrue(E.scale(0.1).isValid)
        for bad in [0, -0.1, 1.5, Double.nan, Double.infinity] {
            XCTAssertTrue(E.scale(bad).ticks.isEmpty, "\(bad)")
            XCTAssertFalse(E.scale(bad).isValid, "\(bad)")
        }
    }

    // MARK: - The goal outlook (part four before kickoff)

    /// The reference outlook's seven full-match totals, admitted. Only the two
    /// served as Over legs make a stem; neither row's clock is provably its own.
    func testBeforeKickoffTheGoalOutlookIsHollowStemsOneForEachOverLine() throws {
        let card = try XCTUnwrap(G.input(try F.detail(F.hullDetail), markets: try F.markets(X.hullExactMarkets),
                                         admitted: X.fullTotals, host: F.propHost(F.hullNow)))
        XCTAssertEqual(card.phase, .before)
        XCTAssertEqual(card.title, G.Words.beforeTitle)
        XCTAssertEqual(card.markStyle, .stems)
        XCTAssertNil(card.actual)
        XCTAssertNil(card.projection)
        // An Under leg is never complemented into a stem.
        XCTAssertEqual(card.milestones.map(\.id), ["238847193", "237512062"])
        XCTAssertEqual(card.milestones.map(\.quantityLabel), ["1+", "2+"])
        XCTAssertTrue(card.milestones.allSatisfy { $0.before == nil && $0.beforeMissing == R.Words.noRecentUpdate })
        XCTAssertTrue(card.milestones.allSatisfy { $0.result == .unconfirmed(R.Words.resultUnavailable) })
    }

    /// CONSTRUCTED owner proof: the two Over markets' clocks named as their own.
    func testWhenTheOwnerProvesARowsClockTheOutlookShowsItsRecentChanceAndStillRefusesAnOldOne() throws {
        let event = try F.detail(F.hullDetail)
        let markets = try F.markets(X.hullExactMarkets)
        let host = F.propHost(F.hullNow)
        let card = try XCTUnwrap(G.input(event, markets: markets, admitted: X.fullTotals,
                                         ownClock: [63390534, 62958651], host: host))
        // 1+ observed 04:30:03Z — 27 minutes before the capture: recent, on its own clock.
        XCTAssertEqual(card.milestones[0].before, G.observation(R.observation(
            0.915, at: "2026-10-11T04:30:03.087634+00:00".asDate!, lead: R.Words.recorded,
            venue: SourceLabels.label(for: "polymarket"), host: host)))
        // 2+ observed 00:44:02Z — over four hours old: still no figure.
        XCTAssertNil(card.milestones[1].before)
        XCTAssertEqual(card.milestones[1].beforeMissing, R.Words.noRecentUpdate)
        // The proof is per market: an unproved market keeps refusing.
        let one = try XCTUnwrap(G.input(event, markets: markets, admitted: X.fullTotals, ownClock: [62958651], host: host))
        XCTAssertNil(one.milestones[0].before)
    }
